:root {
  /* Colors */
  --color-paper-canvas: #ffffff;
  --color-fog-surface: #f6f6f8;
  --color-frosted-pane: #ffffffbf;
  --color-frosted-veil: #ffffff80;
  --color-ink-wash: #111a4a08;
  --color-jet-nav: #12161e;
  --color-ink-navy: #111a4a;
  --color-graphite-label: #232730;
  --color-slate-caption: #7c7f88;
  --color-ash-tertiary: #a9acb6;
  --color-quartz-border: #e3e4e8;
  --color-forest-signal: #167e6c;
  --color-ember-receipt: #ec652b;

  /* Typography — Font Families */
  --font-suisse-intl: "Suisse Intl", "SuisseIntl", ui-sans-serif, system-ui, -apple-system, BlinkMacSystemFont, "Segoe UI", Roboto, sans-serif;
  --font-sf-mono: "SF Mono", "SFMono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;
  --font-suisse-intl-mono: "Suisse Intl Mono", "SuisseIntlMono", ui-monospace, SFMono-Regular, Menlo, Monaco, Consolas, monospace;

  /* Typography — Scale */
  --text-small: 10px;
  --leading-small: 1.5;
  --tracking-small: 0px;
  --text-caption: 12px;
  --leading-caption: 1.5;
  --tracking-caption: 0px;
  --text-body-sm: 14px;
  --leading-body-sm: 1.5;
  --tracking-body-sm: 0px;
  --text-body: 16px;
  --leading-body: 1.375;
  --tracking-body: 0px;
  --text-body-lg: 20px;
  --leading-body-lg: 1.4;
  --tracking-body-lg: 0px;
  --text-subheading: 24px;
  --leading-subheading: 1.1;
  --tracking-subheading: -0.24px;
  --text-heading-sm: 28px;
  --leading-heading-sm: 1.1;
  --tracking-heading-sm: -0.28px;
  --text-heading: 40px;
  --leading-heading: 1.1;
  --tracking-heading: -0.8px;
  --text-heading-lg: 52px;
  --leading-heading-lg: 1.1;
  --tracking-heading-lg: -1.56px;
  --text-display: 60px;
  --leading-display: 1;
  --tracking-display: -0.6px;

  /* Typography — Weights */
  --font-weight-light: 300;
  --font-weight-regular: 400;
  --font-weight-medium: 500;
  --font-weight-semibold: 600;

  /* Spacing */
  --spacing-2: 2px;
  --spacing-4: 4px;
  --spacing-7: 7px;
  --spacing-8: 8px;
  --spacing-12: 12px;
  --spacing-16: 16px;
  --spacing-20: 20px;
  --spacing-24: 24px;
  --spacing-32: 32px;
  --spacing-40: 40px;
  --spacing-48: 48px;
  --spacing-72: 72px;
  --spacing-80: 80px;
  --spacing-96: 96px;
  --spacing-120: 120px;
  --spacing-144: 144px;

  /* Layout */
  --layout-page-max-width: 1112px;
  --layout-section-gap: 144px;
  --layout-card-padding: 20px;
  --layout-element-gap: 8px;

  /* Border Radius */
  --radius-sm: 2px;
  --radius-md: 4px;
  --radius-lg: 6px;
  --radius-xl: 8px;
  --radius-2xl: 12px;
  --radius-3xl: 18px;
  --radius-full: 9999px;

  /* Named Radii */
  --radius-cards: 8px;
  --radius-buttons: 8px;
  --radius-tags: 8px;
  --radius-badges: 4px;
  --radius-avatars: 8px;
  --radius-inner-tiles: 6px;
  --radius-small-elements: 2px;
  --radius-sections: 12px;
  --radius-nav: 12px;
  --radius-pills: 9999px;

  /* Shadows */
  --shadow-subtle: rgba(0, 0, 0, 0.1) 0px 1px 2px 0px;
  --shadow-subtle-2: rgb(255, 255, 255) 0px 0px 0px 1px inset;
  --shadow-sm: rgba(255, 255, 255, 0) 0px 1px 1px 0px, rgba(87, 90, 100, 0.12) 0px 0px 0px 1px;
  --shadow-sm-2: rgba(0, 0, 0, 0.05) 0px 0px 0px 1px inset;
  --shadow-md: rgba(17, 26, 74, 0.1) 0px 1px 3px 0px, rgba(17, 26, 74, 0.05) 0px 1px 0px 0px, rgba(255, 255, 255, 0.5) 0px 1px 0px 0px inset, rgba(255, 255, 255, 0.5) 0px 1px 4px 0px inset;
  --shadow-md-2: rgb(17, 26, 74) 0px 0px 0px 1px, rgba(0, 0, 0, 0.25) 0px 2px 4px 0px, rgba(0, 0, 0, 0.25) 0px 1px 2px 0px;
  --shadow-md-3: rgba(0, 0, 0, 0.05) 0px 0px 0px 1px inset, rgba(0, 0, 0, 0.1) 0px -1px 0px 0px inset, rgba(0, 0, 0, 0.02) 0px -48px 24px -24px inset, rgba(0, 0, 0, 0.05) 0px 4px 8px 0px, rgba(0, 0, 0, 0.05) 0px 2px 4px 0px, rgba(0, 0, 0, 0.05) 0px 1px 1px 0px;
  --shadow-lg: rgba(0, 0, 0, 0.05) 0px 0px 0px 1px, rgba(0, 0, 0, 0.15) 0px 2px 8px 0px;
  --shadow-lg-2: rgba(0, 0, 0, 0.1) 0px 4px 8px 0px, rgba(0, 0, 0, 0.1) 0px 2px 4px 0px, rgba(0, 0, 0, 0.25) 0px 1px 1px 0px;
  --shadow-xl: rgba(0, 0, 0, 0.024) 0px 0px 0px 1px, rgba(0, 0, 0, 0.05) 0px 16px 32px 0px, rgba(0, 0, 0, 0.1) 0px 4px 8px 0px;
  --shadow-xl-2: rgba(0, 0, 0, 0.02) 0px 40px 32px 0px, rgba(0, 0, 0, 0.03) 0px 22px 18px 0px, rgba(0, 0, 0, 0.03) 0px 12px 10px 0px, rgba(0, 0, 0, 0.04) 0px 7px 5px 0px, rgba(0, 0, 0, 0.07) 0px 3px 2px 0px;

  /* Surfaces */
  --surface-paper-canvas: #ffffff;
  --surface-fog-surface: #f6f6f8;
  --surface-frosted-pane: #ffffffbf;
  --surface-ink-navy: #111a4a;
}

